insert into public.challenges (relationship_type, title, description, minutes, category, is_shared, tier)
values
  ('romantic', 'Breakfast at the table', 'Sit down for breakfast together, even a quick one. Phones stay in another room until the plates are cleared.', 15, 'together', true, 'premium'),
  ('romantic', 'Tea and ten questions', 'Make two warm drinks and take turns asking each other questions you have never asked before.', 20, 'together', true, 'premium'),
  ('romantic', 'Plan a small adventure', 'Pick a place neither of you has been, near or far, and plan the day together on paper.', 20, 'together', true, 'premium'),
  ('romantic', 'Watch the sunset', 'Find a spot with a view of the sky and stay until the light is gone. No photos needed.', 20, 'together', true, 'premium'),
  ('romantic', 'Tidy one corner as a team', 'Choose one drawer, shelf or corner and sort it out together. Music allowed, scrolling not.', 20, 'together', true, 'premium'),
  ('romantic', 'Bake something sweet', 'Cookies, banana bread, anything that makes the kitchen smell good. Share the first piece.', 30, 'together', true, 'premium'),
  ('romantic', 'Rose, thorn and bud', 'Each share the best part of your day, the hard part, and one thing you are looking forward to.', 10, 'together', true, 'premium'),
  ('romantic', 'Dream out loud', 'Spend a while talking about one thing you would love to do together in the next year.', 20, 'together', true, 'premium'),
  ('romantic', 'Grocery run for two', 'Shop for the week side by side with a paper list. Each of you adds one treat for the other.', 20, 'together', true, 'premium'),
  ('romantic', 'Look through old photos', 'Pull out printed photos or an album and tell each other the stories behind them.', 20, 'together', true, 'premium'),
  ('romantic', 'Slow morning', 'Stay in, make coffee, and give the first hour of the day to each other before any screen.', 30, 'together', true, 'premium'),
  ('romantic', 'Picnic, indoors or out', 'Spread a blanket in the park or on the living room floor and eat together with nothing else going on.', 30, 'together', true, 'premium'),
  ('romantic', 'Read side by side', 'Each bring a book, share the couch, and read for a while. Swap one favorite line at the end.', 20, 'together', true, 'premium'),
  ('romantic', 'Make a playlist for us', 'Take turns choosing songs that remind you of each other, then listen to it start to finish.', 20, 'together', true, 'premium'),
  ('romantic', 'Stargaze for a while', 'Step outside after dark, look up, and see how many stars or planets you can find together.', 20, 'together', true, 'premium'),
  ('romantic', 'Weekly check-in', 'Sit down once this week to talk about what went well for the two of you and what you each need next week.', 25, 'together', true, 'premium'),
  ('romantic', 'Dinner from somewhere far away', 'Choose a place you would love to visit and make a dish from there, figuring it out as you go.', 30, 'together', true, 'premium'),
  ('romantic', 'Phone-free date night', 'A whole evening out or in, planned by both of you, with both phones tucked away from start to finish.', 45, 'together', true, 'premium'),
  ('romantic', 'Bring them a coffee or tea', 'Make your partner''s favorite warm drink, just the way they like it, without being asked.', 5, 'kindness', false, 'premium'),
  ('romantic', 'Take a chore off their list', 'Quietly do one task your partner usually handles, so they don''t have to today.', 15, 'kindness', false, 'premium'),
  ('romantic', 'Give a real compliment', 'Tell your partner one specific thing you admire about them, out loud and face to face.', 5, 'kindness', false, 'premium'),
  ('romantic', 'Plan a small surprise', 'A favorite snack, a flower, a silly drawing. Something little that says you were thinking of them.', 15, 'kindness', false, 'premium'),
  ('romantic', 'Listen all the way through', 'Ask about their day and listen until they are done. No fixing, no phone, just you.', 10, 'kindness', false, 'premium'),
  ('romantic', 'Make their favorite meal', 'Cook the dish your partner loves most and serve it with a little ceremony.', 30, 'kindness', false, 'premium'),
  ('romantic', 'Say thank you for something small', 'Notice one everyday thing your partner does and thank them for it properly.', 5, 'kindness', false, 'premium'),
  ('romantic', 'Give a shoulder rub', 'Ten unhurried minutes for tired shoulders, with nothing expected in return.', 10, 'kindness', false, 'premium'),
  ('romantic', 'Pack them a lunch', 'Put together tomorrow''s lunch for your partner and tuck in a tiny note.', 15, 'kindness', false, 'premium'),
  ('romantic', 'Warm up their morning', 'Do one thing that makes their morning easier: clear the car, set out breakfast, start the kettle.', 10, 'kindness', false, 'premium'),
  ('romantic', 'Tell them a favorite memory', 'Share one memory of the two of you that still makes you smile, and why it stayed with you.', 10, 'kindness', false, 'premium'),
  ('romantic', 'Give them an hour off', 'Take over whatever needs doing for an hour so your partner can rest or do something just for them.', 30, 'kindness', false, 'premium'),
  ('romantic', 'Hide three little notes', 'Leave three short notes in places your partner will find through the day: a pocket, a mirror, a mug.', 15, 'kindness', false, 'premium'),
  ('romantic', 'Ask about their dream', 'Ask your partner about something they are hoping for, and find one small way you could help.', 10, 'kindness', false, 'premium'),
  ('romantic', 'Greet them at the door', 'When your partner comes home, stop what you are doing and give them a proper hello.', 5, 'kindness', false, 'premium'),
  ('romantic', 'Draw them something', 'A portrait, a comic about your day, a map of your first date. Skill is not required.', 15, 'kindness', false, 'premium'),
  ('romantic', 'Call someone they love', 'Reach out to a friend or family member your partner cares about, just to be kind to their people.', 15, 'kindness', false, 'premium'),
  ('romantic', 'Run them a bath or set up a rest', 'Prepare a cozy half hour for your partner: a bath, a blanket and a book, their favorite chair.', 15, 'kindness', false, 'premium'),
