  ('romantic', 'Learn a card trick', 'Learn one card trick or coin trick on your own, then perform it for your partner.', 15, 'offline_fun', false, 'premium'),
  ('romantic', 'Museum or gallery visit', 'Go and see something together. Each choose one piece you would take home and say why.', 45, 'offline_fun', true, 'premium'),
  ('romantic', 'Candlelight evening', 'Turn off the lights and screens for an hour and spend it by candlelight, talking or playing a game.', 30, 'offline_fun', true, 'premium'),
  ('romantic', 'Make a time capsule', 'Each write a letter to your future selves, add a few small keepsakes, and seal it with a date to open.', 30, 'offline_fun', true, 'premium'),
  ('romantic', 'Morning stretch together', 'Ten easy minutes of stretching side by side before the day begins.', 10, 'movement', true, 'premium'),
  ('romantic', 'Dance in the kitchen', 'Put on three songs you both love and dance while dinner cooks.', 10, 'movement', true, 'premium'),
  ('romantic', 'Bike ride for two', 'Take the bikes out for a ride with no particular destination.', 30, 'movement', true, 'premium'),
  ('romantic', 'Take the long way home', 'Walk home together by a route you don''t usually take and notice three new things.', 20, 'movement', true, 'premium'),
  ('romantic', 'Hike somewhere green', 'Find a trail, a forest path or a big park and spend a good while walking in it together.', 45, 'movement', true, 'premium'),
  ('romantic', 'Play catch or frisbee', 'Take a ball or a frisbee outside and play until one of you calls for a break.', 20, 'movement', true, 'premium'),
  ('romantic', 'Yoga for two', 'Roll out two mats, or two towels, and move through a gentle routine at the same pace.', 20, 'movement', true, 'premium'),
  ('romantic', 'Swim together', 'Head to a pool, a lake or the sea and get in the water together.', 30, 'movement', true, 'premium'),
  ('romantic', 'Garden or balcony hour', 'Weed, water, sweep and plant together until the space looks loved.', 30, 'movement', true, 'premium'),
  ('romantic', 'After-dinner stroll', 'A short walk around the neighborhood after you eat, hand in hand if you like.', 15, 'movement', true, 'premium'),
  ('romantic', 'Try a new sport', 'Badminton, bowling, climbing, table tennis. Pick something neither of you is good at yet.', 45, 'movement', true, 'premium'),
  ('romantic', 'Stairs instead, all day', 'Skip the lift and the escalator for a whole day, then tell your partner how it went.', 10, 'movement', false, 'premium'),
